INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Marketing in der IT nur aus Werbung besteht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch Marktforschung"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Marketingstrategie für IT-Dienstleistungen entwickle?', 3, '[{"text": "Zielgruppenanalyse", "correct": true, "because": "Bestimmt Fokus"}, {"text": "Schnellste Kampagne", "correct": false, "because": "Effektivität zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer Marketingstrategie in der IT?', 5, '[{"text": "Marktforschung", "correct": true, "because": "Analysiert Bedarf"}, {"text": "Werbekampagnen", "correct": true, "because": "Fördert Bekanntheit"}, {"text": "Hardwarewartung", "correct": false, "because": "Kein Marketingfaktor"}, {"text": "Büromöbel", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Marketing erhöht die Sichtbarkeit von IT-Produkten. b) Es ist immer kostenlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten entstehen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Marketing für IT-Dienstleistungen plane?', 4, '[{"text": "Zielgruppenbedarf", "correct": false, "because": "Steuert Strategie"}, {"text": "Budget", "correct": false, "because": "Bestimmt Umfang"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marketingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Marketing in der IT immer online erfolgt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch offline möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Marketing für IT-Produkte?', 3, '[{"text": "Kundengewinnung", "correct": true, "because": "Erhöht Absatz"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Effektivität zählt"}, {"text": "Weniger Werbung", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sind typisch für IT-Marketing?', 5, '[{"text": "Online-Werbung", "correct": true, "because": "Erreicht Zielgruppe"}, {"text": "Social Media", "correct": true, "because": "Fördert Interaktion"}, {"text": "Büroplanung", "correct": false, "because": "Irrelevant"}, {"text": "Hardwarewartung", "correct": false, "because": "Kein Marketing"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Marketing für IT-Dienstleistungen nutzt SEO. b) Es ist immer teuer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Marketingstrategie in der IT?', 4, '[{"text": "Marktanalyse", "correct": false, "because": "Bestimmt Bedarf"}, {"text": "Werbebudget", "correct": false, "because": "Sichert Umsetzung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marketingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Marketing in der IT immer auf große Firmen ausgerichtet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für KMU"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Marketing für IT-Dienstleistungen?', 4, '[{"text": "Kundenbindung", "correct": true, "because": "Fördert Loyalität"}, {"text": "Markenbekanntheit", "correct": true, "because": "Erhöht Sichtbarkeit"}, {"text": "Schnellere Server", "correct": false, "because": "Kein Marketingvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Marketing in der IT nur Werbung ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst Strategien"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Marketing für ein IT-Produkt zu planen?', 3, '[{"text": "Zielgruppenanalyse", "correct": true, "because": "Richtet Kampagne aus"}, {"text": "Günstigste Werbung", "correct": false, "because": "Effektivität wichtiger"}, {"text": "Bunte Flyer", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Marketing kann Online-Präsenz fördern. b) Es ist immer offline durchgeführt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch online möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich beim Marketing für IT?', 5, '[{"text": "Kundensegmente", "correct": true, "because": "Bestimmt Zielgruppe"}, {"text": "Werbekanäle", "correct": true, "because": "Erreicht Kunden"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Marketing für IT-Dienstleistungen plane?', 3, '[{"text": "Kampagnenstrategie", "correct": false, "because": "Bestimmt Erfolg"}, {"text": "Budgetplanung", "correct": false, "because": "Sichert Umsetzung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marketingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Marketing in der IT immer teuer?', 3, '[{"text": "Nein", "correct": true, "because": "Kosten variieren"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Marketing für IT nur digitale Kanäle nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch offline möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für erfolgreiches IT-Marketing?', 4, '[{"text": "Kundenorientierung", "correct": true, "because": "Erfüllt Bedarf"}, {"text": "Schnellste Kampagne", "correct": false, "because": "Effektivität zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
